output:
data "aws_ssm_parameter" "al2023" {
  name = "/aws/service/ami-amazon-linux-latest/al2023-ami-kernel-default-x86_64"
}

resource "aws_instance" "al" {
  ami           = data.aws_ssm_parameter.al2023.value
  instance_type = "t3.micro"

  tags = {
    Name = "al2023-node"
  }
}

output "ami_id" {
  value = data.aws_ssm_parameter.al2023.value
}

data "aws_availability_zones" "available" {
  state = "available"
}

output "az_names" {
  value = slice(data.aws_availability_zones.available.names, 0, 3)
}

data "aws_caller_identity" "current" {}

output "account_id" {
  value = data.aws_caller_identity.current.account_id
}

output "caller_arn" {
  value = data.aws_caller_identity.current.arn
}

data "aws_region" "current" {}

output "region" {
  value = data.aws_region.current.name
}

output "region_endpoint" {
  value = data.aws_region.current.endpoint
}

data "aws_s3_bucket" "existing" {
  bucket = var.existing_bucket_name
}

output "existing_bucket_arn" {
  value = data.aws_s3_bucket.existing.arn
}

variable "existing_bucket_name" {
  type = string
}

data "aws_route53_zone" "public" {
  name         = "example.com"
  private_zone = false
}

output "zone_id" {
  value = data.aws_route53_zone.public.zone_id
}

data "aws_ebs_volume" "data" {
  filter {
    name   = "tag:Name"
    values = ["shared-data-volume"]
  }
}

output "volume_device" {
  value = data.aws_ebs_volume.data.device_name
}

data "terraform_remote_state" "network" {
  backend = "s3"

  config = {
    bucket = "acme-terraform-state"
    key    = "network/terraform.tfstate"
    region = "us-east-1"
  }
}

output "vpc_id" {
  value = data.terraform_remote_state.network.outputs.vpc_id
}

data "aws_eks_cluster" "this" {
  name = var.cluster_name
}

output "cluster_endpoint" {
  value = data.aws_eks_cluster.this.endpoint
}

output "cluster_ca" {
  value     = data.aws_eks_cluster.this.certificate_authority[0].data
  sensitive = true
}

variable "cluster_name" {
  type = string
}

variable "db_password" {
  type      = string
  sensitive = true
}

resource "aws_db_instance" "app" {
  identifier     = "app-db"
  engine         = "postgres"
  instance_class = "db.t4g.micro"
  allocated_storage = 20
  username       = "app"
  password       = var.db_password
  skip_final_snapshot = true
}

output "db_endpoint" {
  value = aws_db_instance.app.endpoint
}

resource "aws_sqs_queue" "events" {
  name = "events"
}

resource "aws_sns_topic" "alerts" {
  name = "alerts"
}

output "notification_arns" {
  value = {
    events_queue = aws_sqs_queue.events.arn
    alerts_topic = aws_sns_topic.alerts.arn
  }
}

data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

output "default_vpc_id" {
  value = data.aws_vpc.default.id
}

output "first_default_subnet" {
  value = tolist(data.aws_subnets.default.ids)[0]
}

data "aws_acm_certificate" "wildcard" {
  domain      = "*.example.com"
  statuses    = ["ISSUED"]
  most_recent = true
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = var.lb_arn
  port              = 443
  protocol          = "HTTPS"
  certificate_arn   = data.aws_acm_certificate.wildcard.arn

  default_action {
    type             = "forward"
    target_group_arn = var.target_group_arn
  }
}

variable "lb_arn" {
  type = string
}

variable "target_group_arn" {
  type = string
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

locals {
  bucket_arn = "arn:${data.aws_partition.current.partition}:s3:::acme-shared"
}

output "shared_bucket_arn" {
  value = local.bucket_arn
}

data "aws_prefix_list" "s3" {
  name = "com.amazonaws.${var.region}.s3"
}

resource "aws_vpc_security_group_egress_rule" "s3" {
  security_group_id = var.security_group_id
  prefix_list_id    = data.aws_prefix_list.s3.id
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

variable "region" {
  type = string
}

variable "security_group_id" {
  type = string
}

data "aws_lambda_function" "existing" {
  function_name = var.function_name
}

output "runtime" {
  value = data.aws_lambda_function.existing.runtime
}

output "last_modified" {
  value = data.aws_lambda_function.existing.last_modified
}

variable "function_name" {
  type = string
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_availability_zones" "available" {
  state = "available"
}

output "environment_info" {
  value = {
    account_id      = data.aws_caller_identity.current.account_id
    region          = data.aws_region.current.name
    available_zones = data.aws_availability_zones.available.names
  }
}

data "aws_security_group" "app" {
  filter {
    name   = "tag:Name"
    values = ["app-tier"]
  }

  filter {
    name   = "vpc-id"
    values = [var.vpc_id]
  }
}

output "app_security_group_id" {
  value = data.aws_security_group.app.id
}

variable "vpc_id" {
  type = string
}

variable "environment" {
  type = string
}

resource "aws_sns_topic" "events" {
  name = "events-${var.environment}"
}

output "topic_name" {
  value = aws_sns_topic.events.name
}

output "criticality" {
  value = var.environment == "prod" ? "high" : "normal"
}

variable "project" {
  type = string
}

locals {
  fqdn = "${var.project}.internal.example.com"
}

resource "aws_route53_record" "app" {
  zone_id = var.zone_id
  name    = local.fqdn
  type    = "A"
  ttl     = 300
  records = [var.app_ip]
}

output "service_url" {
  value = "https://${local.fqdn}"
}

variable "zone_id" {
  type = string
}

variable "app_ip" {
  type = string
}
